const fs = require('node:fs');
const path = require('node:path');
const base = process.env.WORK_DIR || '/work';
const t = (name, f) => { try { console.log(name, String(f())); } catch (e) { console.log(name, 'ERR', e && e.message); } };
const dir = path.join(base, 'dbgfs');
t('dir', () => typeof dir + dir.slice(-5));
t('mkdir-norec', () => fs.mkdirSync(dir));
t('exists', () => fs.existsSync(dir));
t('mkdir-rec2', () => fs.mkdirSync(path.join(dir, 'x', 'y'), { recursive: true }));
t('write', () => fs.writeFileSync(path.join(dir, 'a.txt'), 'hello'));
t('read', () => fs.readFileSync(path.join(dir, 'a.txt'), 'utf8'));
t('append', () => fs.appendFileSync(path.join(dir, 'a.txt'), ' more'));
t('stat', () => { const s = fs.statSync(path.join(dir, 'a.txt')); return s.isFile() + ' ' + s.isDirectory() + ' ' + s.size; });
t('statdir', () => fs.statSync(dir).isDirectory());
t('readdir', () => fs.readdirSync(dir).sort().join(','));
t('enoent', () => { try { fs.readFileSync(path.join(dir, 'nope')); } catch (e) { return e.code; } });
t('unlink', () => fs.unlinkSync(path.join(dir, 'a.txt')));
t('rmdir', () => fs.rmdirSync(path.join(dir, 'x', 'y')));
t('promises', () => typeof fs.promises + typeof fs.promises.writeFile);
